-- ---------- Verification ----------
SELECT COUNT(*) AS total_items FROM items;
SELECT c.name, c.vat_rate, COUNT(i.id) AS items
FROM categories c LEFT JOIN items i ON i.category_id = c.id
GROUP BY c.id ORDER BY items DESC;
